"""Exact money helpers: half-up rounding, cent allocation by largest remainders, position ordering."""
from __future__ import annotations

import re
from decimal import ROUND_CEILING, ROUND_FLOOR, ROUND_HALF_UP, Decimal, localcontext

CENT = Decimal("0.01")


def half_up(x: Decimal, places: int = 2) -> Decimal:
    return Decimal(x).quantize(Decimal(1).scaleb(-places), rounding=ROUND_HALF_UP)


def ceil_int(x: Decimal) -> int:
    return int(Decimal(x).to_integral_value(rounding=ROUND_CEILING))


def div(a: Decimal, b: Decimal) -> Decimal:
    """Division with enough precision that later half-up rounding to cents is exact in practice."""
    with localcontext() as ctx:
        ctx.prec = 50
        return Decimal(a) / Decimal(b)


def position_key(position: str):
    """Ascending order of position identifiers: numeric parts compare as numbers ("2" < "10", "1.2" < "1.10")."""
    parts = re.split(r"(\d+)", str(position))
    return tuple((0, int(p), "") if p.isdigit() else (1, 0, p) for p in parts if p != "")


def allocate_cents(total: Decimal, weights: dict[str, Decimal]) -> dict[str, Decimal]:
    """Split `total` (EUR, whole cents) over `weights` proportionally, in cents: everyone gets the floor of their
    share, the remaining cents go one each to the largest fractional remainders, ties by ascending position id.
    Rules 25 and 26."""
    cents = int(half_up(total) / CENT)
    weight_sum = sum(weights.values(), Decimal(0))
    if not weights:
        return {}
    if weight_sum <= 0:
        raise ValueError("allocation weights sum to zero")
    shares = {k: div(Decimal(cents) * w, weight_sum) for k, w in weights.items()}
    floors = {k: int(s.to_integral_value(rounding=ROUND_FLOOR)) for k, s in shares.items()}
    left = cents - sum(floors.values())
    order = sorted(weights, key=lambda k: (-(shares[k] - floors[k]), position_key(k)))
    for k in order[:left]:
        floors[k] += 1
    return {k: Decimal(c) * CENT for k, c in floors.items()}

"""From raw facts to resolved ones: which records count (authority and time), the final quantity, the governing
requirement and the matching material. Every function appends what it could not decide to `issues`."""
from __future__ import annotations

from dataclasses import replace
from datetime import date, datetime, timezone
from decimal import Decimal

from facts import (Assignment, AssignmentKind, Attr, Facts, Material, Requirement, SpecRevision, TenderPosition, Unit,
                   dec, mail_address, norm_key, norm_text)

from .money import position_key

_EPOCH = datetime(1, 1, 1, tzinfo=timezone.utc)


def _ts(d) -> datetime:
    """Sort key for a record date; records without a date sort first, so dated records win."""
    if d is None:
        return _EPOCH
    if isinstance(d, datetime):
        return d if d.tzinfo else d.replace(tzinfo=timezone.utc)
    return datetime(d.year, d.month, d.day, tzinfo=timezone.utc)


def not_after(d, limit) -> bool:
    """`d` is no later than `limit`. When either side is a plain date, the comparison is by calendar day."""
    if d is None:
        return True
    if isinstance(d, datetime) and isinstance(limit, datetime):
        return _ts(d) <= _ts(limit)
    return _day(d) <= _day(limit)


def _day(d) -> date:
    return d.date() if isinstance(d, datetime) else d


def _date(record):
    return record.source.date if record.source else None


def _sender(record) -> str:
    return mail_address(record.source.sender) if record.source else ""


# ---------------------------------------------------------------------------------------------------------------------
# Rule 21: authority and time


def authorized(record, facts: Facts, issues: list[str]) -> bool:
    """The record is for the exact tender, not later than the scenario date, and from its authorized sender."""
    kind = type(record).__name__
    if norm_key(record.reference) != norm_key(facts.tender_reference):
        return False
    if not not_after(_date(record), facts.scenario_date):
        return False
    if _date(record) is None:
        issues.append(f"{kind} {getattr(record, 'key', '')}: no date, cannot check it against the scenario date")
    sender = _sender(record)
    local = facts.authority.get(kind)
    if local and sender:
        want_local = local.split("@")[0].lower()
        got_local, _, got_domain = sender.partition("@")
        if got_local != want_local:
            return False
        if facts.bidder_domain and got_domain != facts.bidder_domain.lower().lstrip("@"):
            return False
    elif local:
        issues.append(f"{kind} {getattr(record, 'key', '')}: sender unknown, authority not checked")
    return True


def latest_by_key(records, facts: Facts, issues: list[str], key=lambda r: norm_key(r.key)) -> dict:
    """Rule 21: per key, the latest authorized record. A newer record replaces an older one, whatever it says."""
    best: dict = {}
    for i, r in enumerate(records):
        if not authorized(r, facts, issues):
            continue
        k = key(r)
        rank = (_ts(_date(r)), i)
        if k in best and best[k][0][0] == rank[0]:
            issues.append(f"{type(r).__name__} {k}: two records with the same date; the later one in the list wins")
        if k not in best or rank > best[k][0]:
            best[k] = (rank, r)
    return {k: v[1] for k, v in best.items()}


def discount_approval(facts: Facts, issues: list[str]):
    """Rule 5: the most recent approval from the sales director for this exact tender, or None."""
    want = mail_address(facts.director_address)
    best = None
    for i, a in enumerate(facts.discount_approvals):
        if norm_key(a.reference) != norm_key(facts.tender_reference):
            continue
        if not not_after(_date(a), facts.scenario_date):
            continue
        sender = _sender(a)
        if want and sender and sender != want:
            continue
        if want and not sender:
            issues.append("discount approval: sender unknown, not checked against the sales director")
        rank = (_ts(_date(a)), i)
        if best is None or rank > best[0]:
            best = (rank, a)
    return best[1] if best else None


# ---------------------------------------------------------------------------------------------------------------------
# Tender Q&A


def _qa_rank(entry):
    return (_ts(_date(entry)), position_key(entry.qa_number))


def withdrawn_numbers(facts: Facts) -> set[str]:
    """Rule 13: numbers of Q&A answers withdrawn by a later answer."""
    return {norm_key(w.withdraws) for w in facts.withdrawals if not_after(_date(w), facts.scenario_date)}


def _live(entries, facts: Facts):
    gone = withdrawn_numbers(facts)
    return [e for e in entries if norm_key(e.qa_number) not in gone and not_after(_date(e), facts.scenario_date)]


def assignment(facts: Facts, position: str, kind: AssignmentKind) -> Assignment | None:
    """The latest remaining Q&A assignment of this kind to the position."""
    found = [a for a in _live(facts.assignments, facts) if a.kind == kind and norm_key(a.position) == norm_key(position)]
    return max(found, key=_qa_rank) if found else None


def stated_quantity(facts: Facts, pos: TenderPosition) -> Decimal:
    """Rules 1 and 13: the tender quantity, overridden by the latest remaining Q&A change, in the stated unit."""
    changes = [c for c in _live(facts.quantity_changes, facts) if norm_key(c.position) == norm_key(pos.position)]
    return max(changes, key=_qa_rank).quantity if changes else pos.quantity


def has_withdrawn_change(facts: Facts, pos: TenderPosition) -> bool:
    gone = withdrawn_numbers(facts)
    return any(norm_key(c.qa_number) in gone for c in facts.quantity_changes
               if norm_key(c.position) == norm_key(pos.position))


def final_pieces(facts: Facts, pos: TenderPosition, req: Requirement | None, issues: list[str]) -> int | None:
    """Rule 17: the final quantity in pieces; a Satz is converted with the governing specification's pieces per set."""
    q = stated_quantity(facts, pos)
    if pos.unit == Unit.SET:
        if req is None or req.pieces_per_set is None:
            issues.append(f"position {pos.position}: quantity is in sets, pieces per set unknown")
            return None
        q = q * req.pieces_per_set
    if q != q.to_integral_value():
        issues.append(f"position {pos.position}: quantity {q} is not a whole number of pieces")
        return None
    return int(q)


# ---------------------------------------------------------------------------------------------------------------------
# Specification


def governing_revision(facts: Facts, issues: list[str]) -> SpecRevision | None:
    """Rule 2: the revision marked current. Without exactly one such mark, the latest dated revision not after the
    scenario date among the marked ones (or among all, when none is marked)."""
    if not facts.revisions:
        return None
    marked = [r for r in facts.revisions if r.current]
    if len(marked) == 1:
        return marked[0]
    pool = marked or facts.revisions
    issues.append(f"specification: {len(marked)} revisions marked current; choosing the latest dated one")
    pool = [r for r in pool if not_after(r.date, facts.scenario_date)] or pool
    return max(pool, key=lambda r: _ts(r.date))


def requirement(facts: Facts, revision: SpecRevision | None, ref: str, issues: list[str]) -> Requirement | None:
    """Rules 14 and 20: the requirement in the governing revision, with the scoped amendments applied (latest per
    attribute) and, for usable travel, twice the per-end reserve added to the stroke."""
    if revision is None:
        issues.append(f"requirement {ref}: no governing specification revision")
        return None
    base = next((r for r in revision.requirements if norm_key(r.requirement) == norm_key(ref)), None)
    if base is None:
        issues.append(f"requirement {ref}: not in revision {revision.revision}")
        return None
    latest: dict[Attr, object] = {}
    for a in sorted(_live(facts.amendments, facts), key=_qa_rank):
        if norm_key(a.revision) == norm_key(revision.revision) and norm_key(a.requirement) == norm_key(ref):
            latest[a.attribute] = a.value
    changes = {}
    for attr, value in latest.items():
        changes[attr.value] = value if attr in (Attr.MOUNTING, Attr.CERTIFICATION) else dec(value)
    req = replace(base, **changes)
    if req.usable_travel:
        reserves = latest_by_key(facts.end_reserves, facts, issues,
                                 key=lambda r: (norm_key(r.key), norm_key(r.revision)))
        reserve = reserves.get((norm_key(req.end_reserve_key), norm_key(revision.revision)))
        if reserve is None or req.stroke_mm is None:
            issues.append(f"requirement {ref}: usable travel, but no end reserve {req.end_reserve_key or '(no key)'} "
                          f"for revision {revision.revision}")
            return replace(req, stroke_mm=None)
        req = replace(req, stroke_mm=req.stroke_mm + 2 * reserve.reserve_mm)
    return req


# ---------------------------------------------------------------------------------------------------------------------
# Material


_NO_CERT = {"", "-", "–", "—", "keine", "keine gefordert", "nicht gefordert", "ohne", "none", "n/a", "entfällt",
            "keine anforderung", "keine zertifizierung"}


def _cert(text: str | None) -> str:
    t = norm_text(text).rstrip(".")
    return "" if t in _NO_CERT else t


def _same(a, b) -> bool:
    return a is not None and b is not None and Decimal(a) == Decimal(b)


def matches(m: Material, req: Requirement) -> bool:
    return (_same(m.bore_mm, req.bore_mm) and _same(m.stroke_mm, req.stroke_mm)
            and _same(m.pressure_bar, req.pressure_bar)
            and m.mounting is not None and norm_text(m.mounting) == norm_text(req.mounting)
            and _cert(m.certification) == _cert(req.certification))


def requirement_complete(req: Requirement) -> bool:
    return None not in (req.bore_mm, req.stroke_mm, req.pressure_bar, req.mounting)


def select_material(facts: Facts, req: Requirement, position: str, issues: list[str]) -> Material | None:
    """Rule 3: the active material whose bore, stroke, pressure, mounting and certification match exactly."""
    hits = [m for m in facts.materials if matches(m, req)]
    active = [m for m in hits if m.active is True]
    if not active:
        unknown = [m for m in hits if m.active is None]
        if unknown:
            issues.append(f"position {position}: matching material {unknown[0].material_number} has unknown status")
            active = unknown
    if len(active) > 1:
        numbers = ", ".join(m.material_number for m in active)
        issues.append(f"position {position}: several active materials match ({numbers}); taking the first")
    return active[0] if active else None

"""Price building blocks: the valid condition and scale, currency conversion, metal index, bonus bands."""
from __future__ import annotations

from decimal import Decimal

from facts import BonusBand, Facts, IndexWindow, Material, PriceCondition, norm_key

from .money import div, half_up
from .resolve import _day, _ts, latest_by_key, not_after


def valid_condition(material: Material, facts: Facts, issues: list[str]) -> PriceCondition | None:
    """Rule 4: the price condition valid on the scenario date (bounds inclusive). If several are valid, the one that
    started last."""
    valid = [c for c in material.conditions
             if (c.valid_from is None or not_after(c.valid_from, facts.scenario_date))
             and (c.valid_to is None or not_after(facts.scenario_date, c.valid_to))]
    if not valid:
        issues.append(f"material {material.material_number}: no price condition valid on the scenario date")
        return None
    if len(valid) > 1:
        issues.append(f"material {material.material_number}: {len(valid)} conditions valid; taking the latest start")
    return max(valid, key=lambda c: _ts(c.valid_from))


def scale_price(condition: PriceCondition, pieces: int) -> Decimal | None:
    """Rules 4, 15, 22: price per piece in the condition's currency at the highest scale this position reaches."""
    reached = [s for s in condition.scales if s.min_quantity <= pieces]
    if not reached:
        return None
    best = max(reached, key=lambda s: s.min_quantity)
    return div(best.price, condition.price_unit or Decimal(1))


def base_unit_price(material: Material, pieces: int, facts: Facts, issues: list[str]) -> Decimal | None:
    """The EUR base price per piece before any discount. A foreign currency is converted with the Devisenfixing rate
    and rounded half-up to cents (rule 22); that rounded value is the base from then on. An EUR price stays exact."""
    cond = valid_condition(material, facts, issues)
    if cond is None:
        return None
    price = scale_price(cond, pieces)
    if price is None:
        issues.append(f"material {material.material_number}: no quantity scale reached by {pieces} pieces")
        return None
    currency = norm_key(cond.currency) or "EUR"
    if currency == "EUR":
        return price
    rates = latest_by_key(facts.fx_rates, facts, issues)
    rate = rates.get(norm_key(cond.fx_key))
    if rate is None:
        issues.append(f"material {material.material_number}: price in {currency}, FX key {cond.fx_key or '(none)'} "
                      "not found")
        return None
    if norm_key(rate.currency) and norm_key(rate.currency) != currency:
        issues.append(f"FX key {cond.fx_key}: rate is for {rate.currency}, condition is in {currency}")
        return None
    return half_up(price * rate.eur_per_unit)


def index_rate(material: Material, facts: Facts, issues: list[str]) -> Decimal | None:
    """Rule 28: EUR per kg of the material's metal index on the scenario date, from the latest authorized index
    record. Windows are inclusive; when none is dated, the single listed rate applies."""
    index = latest_by_key(facts.metal_indices, facts, issues).get(norm_key(material.metal_index))
    if index is None:
        issues.append(f"material {material.material_number}: metal index {material.metal_index} not found")
        return None
    day = _day(facts.scenario_date)
    hits = [w for w in index.windows if _in_window(w, day)]
    if not hits:
        issues.append(f"metal index {material.metal_index}: no rate valid on the scenario date")
        return None
    if len(hits) > 1:
        issues.append(f"metal index {material.metal_index}: {len(hits)} windows contain the scenario date")
    return max(hits, key=lambda w: (w.valid_from is not None, w.valid_from or day)).rate_eur_per_kg


def _in_window(w: IndexWindow, day) -> bool:
    return (w.valid_from is None or _day(w.valid_from) <= day) and (w.valid_to is None or day <= _day(w.valid_to))


def bonus_credit(total: Decimal, bands: list[BonusBand]) -> Decimal:
    """Rule 26: each band's percent on the part of the total inside it, summed, rounded half-up once."""
    credit = Decimal(0)
    for band in bands:
        top = total if band.upper is None else min(total, band.upper)
        part = top - band.lower
        if part > 0:
            credit += part * band.percent / 100
    return half_up(credit)

"""From facts to the answer object. Pure and deterministic: the same facts always give the same bid."""
from __future__ import annotations

from collections import defaultdict
from dataclasses import dataclass, field
from decimal import Decimal

from facts import AssignmentKind, DiscountScope, Facts, Material, TenderPosition, norm_key

from . import resolve
from .money import allocate_cents, ceil_int, div, half_up, position_key
from .pricing import base_unit_price, bonus_credit, index_rate

ZERO = Decimal(0)


@dataclass
class Line:
    """Working record for one position; money fields are unrounded EUR, None when unknown."""
    position: str
    material: Material | None = None
    pieces: int | None = None
    base: Decimal | None = None             # per piece, before discount
    mass_surcharge: Decimal | None = None   # per piece, before discount
    setup: Decimal | None = None            # ordinary setup fee, whole position
    pool: Decimal | None = ZERO             # allocated shared setup, whole position
    packaging: Decimal | None = ZERO        # carton cost, whole position
    bonus: Decimal | None = ZERO            # allocated project bonus, whole position
    scope: DiscountScope = DiscountScope.BASE
    lead_weeks: int | None = None
    unit_price: Decimal | None = None


@dataclass
class BidResult:
    answer: dict
    issues: list[str] = field(default_factory=list)
    lines: list[Line] = field(default_factory=list)
    incomplete: list[str] = field(default_factory=list)   # positions whose unit price could not be fully computed


def build_bid(facts: Facts) -> dict:
    """The answer object for the run's answer schema."""
    return evaluate(facts).answer


def evaluate(facts: Facts) -> BidResult:
    """The answer object plus what could not be decided (`issues`) and the per-position working (`lines`)."""
    issues: list[str] = []
    revision = resolve.governing_revision(facts, issues)
    positions = sorted(facts.positions, key=lambda p: position_key(p.position))

    lines: list[Line] = []
    no_match: list[str] = []
    for pos in positions:
        line = Line(pos.position)
        req = resolve.requirement(facts, revision, pos.requirement, issues)
        line.pieces = resolve.final_pieces(facts, pos, req, issues)
        if req is not None and resolve.requirement_complete(req):
            line.material = resolve.select_material(facts, req, pos.position, issues)
            if line.material is None:
                no_match.append(pos.position)
        elif req is not None:
            issues.append(f"position {pos.position}: requirement incomplete, material not selected")
        lines.append(line)

    approval = resolve.discount_approval(facts, issues)
    if no_match:
        issues.append(f"no active material matches position(s) {', '.join(no_match)}: no bid (rule 3)")
        percent = approval.percent if approval and approval.min_order_value is None else ZERO
        answer = _answer(facts, "no_bid", percent, [], ZERO)
        return BidResult(answer, _dedupe(issues), lines, [])

    priced = [ln for ln in lines if ln.material is not None and ln.pieces is not None]
    for ln in priced:
        ln.base = base_unit_price(ln.material, ln.pieces, facts, issues)
    percent = _discount(facts, approval, priced, issues)
    _surcharges(facts, priced, issues)
    _setup_pools(facts, priced, issues)
    _packaging(facts, priced, issues)
    _bonus(facts, priced, issues)
    _scopes(facts, priced, issues)
    _lead_times(facts, priced, issues)

    out, incomplete, total = [], [], ZERO
    for ln in lines:
        if ln.material is None or ln.pieces is None:
            issues.append(f"position {ln.position}: left out (material or quantity unknown)")
            continue
        ln.unit_price = _unit_price(ln, percent)
        if ln.unit_price is None:
            incomplete.append(ln.position)
        unit_price = ln.unit_price if ln.unit_price is not None else ZERO
        total += ln.pieces * unit_price
        out.append(_position(ln, unit_price, issues))
    answer = _answer(facts, "bid", percent, out, half_up(total))
    return BidResult(answer, _dedupe(issues), lines, incomplete)


# ---------------------------------------------------------------------------------------------------------------------
# Order level


def _discount(facts: Facts, approval, lines: list[Line], issues: list[str]) -> Decimal:
    """Rules 5 and 16: the latest approval's percent, or 0 if its minimum undiscounted order value is not reached.
    The order value is final pieces times base price, before discount, without surcharges or setup, in cents."""
    if approval is None:
        return ZERO
    if approval.min_order_value is None:
        return approval.percent
    if any(ln.base is None for ln in lines):
        issues.append("discount threshold computed without positions whose base price is unknown")
    value = half_up(sum((ln.pieces * ln.base for ln in lines if ln.base is not None), ZERO))
    return approval.percent if value >= approval.min_order_value else ZERO


def _members(facts: Facts, lines: list[Line], kind: AssignmentKind) -> dict[str, list[Line]]:
    groups: dict[str, list[Line]] = defaultdict(list)
    for ln in lines:
        a = resolve.assignment(facts, ln.position, kind)
        if a is not None:
            groups[norm_key(a.key)].append(ln)
    return groups


def _surcharges(facts: Facts, lines: list[Line], issues: list[str]):
    """Rule 28: mass surcharge per piece = surcharge mass x index rate on the scenario date. Setup fee as read."""
    for ln in lines:
        m = ln.material
        ln.setup = m.setup_fee_eur if m.setup_fee_eur is not None else ZERO
        if not norm_key(m.metal_index):
            ln.mass_surcharge = ZERO
            continue
        rate = index_rate(m, facts, issues)
        if rate is None or m.surcharge_mass_kg is None:
            if m.surcharge_mass_kg is None:
                issues.append(f"material {m.material_number}: surcharge mass unknown")
            ln.mass_surcharge = None
        else:
            ln.mass_surcharge = m.surcharge_mass_kg * rate


def _setup_pools(facts: Facts, lines: list[Line], issues: list[str]):
    """Rule 25: one pool fee allocated in cents by final pieces x allocation mass."""
    pools = resolve.latest_by_key(facts.setup_pools, facts, issues)
    for key, members in _members(facts, lines, AssignmentKind.SETUP_POOL).items():
        pool = pools.get(key)
        missing = [ln.position for ln in members if ln.material.allocation_mass_kg is None]
        if pool is None or missing:
            issues.append(f"setup pool {key}: " + ("fee not found" if pool is None
                                                    else f"allocation mass unknown for {', '.join(missing)}"))
            for ln in members:
                ln.pool = None
            continue
        weights = {ln.position: ln.pieces * ln.material.allocation_mass_kg for ln in members}
        for ln in members:
            ln.pool = ZERO
        if sum(weights.values(), ZERO) == 0:
            issues.append(f"setup pool {key}: all weights are zero, fee not allocated")
            continue
        shares = allocate_cents(pool.fee_eur, weights)
        for ln in members:
            ln.pool = shares[ln.position]


def _packaging(facts: Facts, lines: list[Line], issues: list[str]):
    """Rule 23: ceil(final pieces / pieces per carton) cartons at the assigned tariff, per position, never pooled."""
    tariffs = resolve.latest_by_key(facts.packaging_tariffs, facts, issues)
    for key, members in _members(facts, lines, AssignmentKind.PACKAGING).items():
        tariff = tariffs.get(key)
        for ln in members:
            size = ln.material.pieces_per_carton
            if tariff is None or not size:
                issues.append(f"position {ln.position}: packaging {key}: "
                              + ("tariff not found" if tariff is None else "pieces per carton unknown"))
                ln.packaging = None
            else:
                ln.packaging = ceil_int(div(ln.pieces, size)) * tariff.eur_per_carton


def _bonus(facts: Facts, lines: list[Line], issues: list[str]):
    """Rule 26: marginal bands on the members' undiscounted goods total, allocated in cents by line goods value."""
    bonuses = resolve.latest_by_key(facts.project_bonuses, facts, issues)
    for key, members in _members(facts, lines, AssignmentKind.PROJECT_BONUS).items():
        bonus = bonuses.get(key)
        if bonus is None or any(ln.base is None for ln in members):
            issues.append(f"project bonus {key}: " + ("bands not found" if bonus is None
                                                       else "a member's base price is unknown"))
            for ln in members:
                ln.bonus = None
            continue
        values = {ln.position: ln.pieces * ln.base for ln in members}
        credit = bonus_credit(sum(values.values(), ZERO), bonus.bands)
        for ln in members:
            ln.bonus = ZERO
        if credit > 0:
            shares = allocate_cents(credit, values)
            for ln in members:
                ln.bonus = shares[ln.position]


def _scopes(facts: Facts, lines: list[Line], issues: list[str]):
    """Rule 12: a position's Konditionsgruppe decides what the discount reduces; without one, the base only."""
    rules = resolve.latest_by_key(facts.condition_groups, facts, issues)
    for key, members in _members(facts, lines, AssignmentKind.CONDITION_GROUP).items():
        rule = rules.get(key)
        if rule is None:
            issues.append(f"Konditionsgruppe {key}: rule not found; using the default (discount on base only)")
            continue
        for ln in members:
            ln.scope = rule.scope


def _lead_times(facts: Facts, lines: list[Line], issues: list[str]):
    """Rules 6, 15, 24: a matching commitment within its ceiling, else stock if it covers the pooled demand of the
    material over all positions, else production."""
    demand: dict[str, int] = defaultdict(int)
    for ln in lines:
        demand[norm_key(ln.material.material_number)] += ln.pieces
    commitments = resolve.latest_by_key(facts.delivery_commitments, facts, issues)
    for ln in lines:
        m = ln.material
        pooled = demand[norm_key(m.material_number)]
        a = resolve.assignment(facts, ln.position, AssignmentKind.DELIVERY)
        if a is not None:
            c = commitments.get(norm_key(a.key))
            if c is None:
                issues.append(f"position {ln.position}: delivery commitment {a.key} not found")
            elif norm_key(c.material_number) == norm_key(m.material_number) and pooled <= c.max_quantity:
                ln.lead_weeks = c.lead_weeks
                continue
        if m.stock is not None and m.stock >= pooled:
            ln.lead_weeks = m.stock_lead_weeks
        elif m.stock is not None:
            ln.lead_weeks = m.production_lead_weeks
        else:
            issues.append(f"material {m.material_number}: stock unknown, using production lead time")
            ln.lead_weeks = m.production_lead_weeks
        if ln.lead_weeks is None:
            issues.append(f"position {ln.position}: lead time unknown")


# ---------------------------------------------------------------------------------------------------------------------
# Position level


def _unit_price(ln: Line, percent: Decimal) -> Decimal | None:
    """Rule 27: discounted base + discounted mass surcharge + (setup + pool + packaging - bonus) / pieces, from
    unrounded components, rounded half-up once."""
    parts = (ln.base, ln.mass_surcharge, ln.setup, ln.pool, ln.packaging, ln.bonus)
    if any(p is None for p in parts):
        return None
    keep = 1 - percent / 100
    base = ln.base * keep if ln.scope in (DiscountScope.BASE, DiscountScope.BASE_AND_SURCHARGE) else ln.base
    mass = ln.mass_surcharge * keep if ln.scope == DiscountScope.BASE_AND_SURCHARGE else ln.mass_surcharge
    once = ln.setup + ln.pool + ln.packaging - ln.bonus
    per_piece = div(once, ln.pieces) if ln.pieces else ZERO
    return half_up(base + mass + per_piece)


def _position(ln: Line, unit_price: Decimal, issues: list[str]) -> dict:
    """One answer entry. An optional breakdown field is left out when it is unknown (blank = unanswered)."""
    entry = {
        "position": ln.position,
        "material_number": ln.material.material_number,
        "quantity": ln.pieces,
        "unit_price": _num(unit_price),
        "lead_time_weeks": ln.lead_weeks if ln.lead_weeks is not None else 0,
    }
    n = ln.pieces
    if ln.base is not None:
        entry["base_unit_price"] = _num(half_up(ln.base))
    if n and None not in (ln.mass_surcharge, ln.setup, ln.pool):
        entry["surcharge_per_unit"] = _num(half_up(ln.mass_surcharge + div(ln.setup + ln.pool, n)))
    if n and ln.packaging is not None:
        entry["packaging_per_unit"] = _num(half_up(div(ln.packaging, n)))
    if ln.bonus is not None:
        entry["rebate_total"] = _num(half_up(ln.bonus))
    return entry


def _answer(facts: Facts, decision: str, percent: Decimal, positions: list[dict], total: Decimal) -> dict:
    return {
        "tender_reference": facts.tender_reference,
        "decision": decision,
        "currency": "EUR",
        "discount_percent": _num(percent),
        "positions": positions,
        "total_net": _num(half_up(total)),
    }


def _num(d: Decimal) -> int | float:
    """JSON number for a Decimal: an int when whole, else a float (exact for two decimals)."""
    return int(d) if d == d.to_integral_value() else float(d)


def _dedupe(items: list[str]) -> list[str]:
    return list(dict.fromkeys(items))

